import{_ as e,o as t,c as o,a5 as r}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"版权、版本与引用","description":"说明《人生进阶指南》的版本、书名、作者署名、许可证、非医疗建议、来源规则与引用方式，并说明本书没有出版机构与 ISBN。","frontmatter":{"title":"版权、版本与引用","description":"说明《人生进阶指南》的版本、书名、作者署名、许可证、非医疗建议、来源规则与引用方式，并说明本书没有出版机构与 ISBN。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-0/copyright.md","filePath":"threads/part-0/copyright.md","lastUpdated":1795392000000}'),n={name:"threads/part-0/copyright.md"};function s(i,a,d,p,l,c){return t(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="版权、版本与引用" tabindex="-1">版权、版本与引用 <a class="header-anchor" href="#版权、版本与引用" aria-label="Permalink to &quot;版权、版本与引用&quot;">​</a></h1><p>这一页记录这本书怎样被命名、授权、引用和更正。它不替代合同或法律意见，只把读者真正需要知道的事情写在明处。</p><h2 id="版本与书名" tabindex="-1">版本与书名 <a class="header-anchor" href="#版本与书名" aria-label="Permalink to &quot;版本与书名&quot;">​</a></h2><p>当前版本为 <strong>1.1.0</strong>，更新日期 <strong>2026-11-23</strong>。中文书名是《人生进阶指南：一个普通人的失败、恢复与重新学习》；英文书名是 <em>Still Here: A Field Guide to Beginning Again</em>。</p><p>目录名 <code>part-1</code>、<code>part-2</code> 等是历史主题标识，不是阅读顺序。书籍的阅读顺序以<a href="./roadmap">本书路线图</a>与各页目录为准。</p><p>版本号变化时，已发布的中文与英文 EPUB、PDF 会同时重建；文件校验值发布在<a href="./../../book-downloads">下载中心</a>，构建清单保存在下载目录里。</p><h2 id="作者与英文版说明" tabindex="-1">作者与英文版说明 <a class="header-anchor" href="#作者与英文版说明" aria-label="Permalink to &quot;作者与英文版说明&quot;">​</a></h2><p>作者：<strong>韩先凯</strong>。英文版署名 <strong>Han Xiankai</strong>。</p><p>中文版是主版本。英文版是独立改写的版本，不是逐字翻译：章节结构、日期与证据对应，但语气、例子和句子长度按英语读者的阅读习惯重写。若两种语言出现理解差异，以中文版的事实与边界为准，并把差异报告给维护者。</p><p>「离谱」是作者早期使用的笔名，也是 2017 年那本《离谱的英语学习指南》的来源。它保留在本页和<a href="./prologue">序章</a>里作为历史说明，不再作为书名或常规署名；英文版不音译这个笔名。</p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><ul><li>正文、翻译、作者创建的图表与模板：<strong>CC BY-NC 4.0</strong>。可以复制、改编与非商业传播，需署名 <code>byoungd and contributors</code>、链接到本仓库、注明来源页面与修改。商业使用不在此许可范围内。</li><li>站点配置、检查脚本、构建代码与测试：<strong>MIT</strong>。</li><li>第三方引用、图片、商标与产品名称：仍归各自权利人所有，不因收录进本仓库而重新授权。</li></ul><p>本仓库是<strong>开放内容项目</strong>，不是 OSI 意义上的开源软件；只有代码部分是按 MIT 授权的开源软件。完整说明见仓库根目录的 <code>LICENSE.md</code>、<code>LICENSE-CONTENT.md</code> 与 <code>LICENSE-CODE.md</code>。</p><h2 id="不是医疗建议" tabindex="-1">不是医疗建议 <a class="header-anchor" href="#不是医疗建议" aria-label="Permalink to &quot;不是医疗建议&quot;">​</a></h2><p>书中关于抑郁、焦虑、恢复、睡眠与工作负荷的内容，是个人经验与公开资料的整理，不构成诊断、治疗方案、药物建议或危机干预。恢复篇不提供药物名称、剂量或停药方案，也不提供可能过期的当地热线号码。</p><p>如果你正在经历持续的低落、失眠、绝望或伤害自己的念头，请先联系可信任的人，并寻求所在地区具备资质的医疗或心理专业支持。先保证安全，再谈成长。本书不能替代照护。</p><h2 id="引用与复核" tabindex="-1">引用与复核 <a class="header-anchor" href="#引用与复核" aria-label="Permalink to &quot;引用与复核&quot;">​</a></h2><p>书中的陈述分为三类：<strong>研究结论</strong>、<strong>个人经验</strong>与<strong>待检验的假设</strong>。只有第一类可以直接复述为证据；第二类只证明作者经历过；第三类必须由读者在自己的任务上复测。</p><p>AI 产品、模型能力、价格、协议与供应商政策按变化速度分级复核：使用政策、安全公告、产品功能与套餐为 30 天；协议规范与实现指南为 60 天；稳定概念为 120 天。页面里的 <code>sources_checked</code> 日期表示外部资料被核验，<code>updated</code> 日期表示正文被修改，两者不能互相替代。</p><p>完整的来源规则见<a href="./../../reference/sources-and-citation">资料、引用与核验说明</a>，条目清单见<a href="./../../reference/bibliography">参考文献</a>。</p><h2 id="勘误与反馈" tabindex="-1">勘误与反馈 <a class="header-anchor" href="#勘误与反馈" aria-label="Permalink to &quot;勘误与反馈&quot;">​</a></h2><ul><li>事实错误、失效链接、翻译差异：通过<a href="https://github.com/byoungd/up/issues/new/choose" target="_blank" rel="noreferrer">问题模板</a>提交，写清页面、原文、来源与建议。</li><li>安全问题、泄露的个人信息或未经授权的第三方图片：不要公开发布，按 <code>SECURITY.md</code> 的私有渠道报告。</li><li>读者实践回执：可以使用<a href="./../../templates/reader-field-note">读者实践回执</a>，但请删除不必要的第三方身份、健康、财务与关系细节。</li></ul><p>修订会在下一次发布时进入正文与 EPUB/PDF；历史版本可以通过 Git 提交记录查看。</p><h2 id="没有出版机构与-isbn" tabindex="-1">没有出版机构与 ISBN <a class="header-anchor" href="#没有出版机构与-isbn" aria-label="Permalink to &quot;没有出版机构与 ISBN&quot;">​</a></h2><p>本书是作者维护的开放书稿，没有通过出版社出版，没有分配 ISBN，也没有纸书发行渠道。EPUB 与 PDF 由本仓库的构建脚本生成，适用于个人阅读与家庭打印，不代表任何出版机构的审校或背书。</p><p>引用本书时，请使用书名、作者、版本号、更新日期与网址，并注明正文采用 CC BY-NC 4.0。仓库提供 <code>CITATION.cff</code>，便于在支持该格式的工具中直接引用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>韩先凯. 人生进阶指南：一个普通人的失败、恢复与重新学习. 1.1.0 版. 2026-11-23.</span></span>
<span class="line"><span>https://byoungd.github.io/up/</span></span></code></pre></div><p>若未来出现正式出版版本，本页会补上出版社、ISBN 与版本对应关系；在那之前，请不要为本书填写任何 ISBN 或出版机构。</p>`,28)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
